function acidPH(Ca,Va,Cb,Vb,pKa,strong){const Vt=(Va+Vb)/1000,CA=Ca*Va/1000/Vt,Na=Cb*Vb/1000/Vt;const Ka=strong?1e6:10**-pKa;let lo=1e-14,hi=10;for(let i=0;i<120;i++){const h=Math.sqrt(lo*hi);const f=h+Na-CA*Ka/(Ka+h)-1e-14/h;if(f>0)hi=h;else lo=h}return -Math.log10(Math.sqrt(lo*hi))}
function endV(Ca,Va,Cb,pKa,strong,pHe){let lo=0,hi=Ca*Va/Cb*1.6;for(let i=0;i<80;i++){const m=(lo+hi)/2;if(acidPH(Ca,Va,Cb,m,pKa,strong)<pHe)lo=m;else hi=m}return(lo+hi)/2}
